import fs from 'node:fs';
import { performance } from 'node:perf_hooks';
import * as D from '../packages/domain/src/index.ts';
import { draftWorld, finishWorld, appendedEventCount, freezeWorld } from '../packages/domain/src/draft.ts';
import { upgradeWorldState } from '../apps/server/src/upgrade-world.ts';
import { resolveResponseEntities } from '../apps/server/src/entity-references.ts';
const report=[]; const requireValue=(condition,message)=>{if(!condition)throw Error(message);};
let w=D.createWorld(73);w.paused=false;D.migrateCognition(w);w=freezeWorld(w);
const event={id:'audit-1',at:0,sequence:1,type:'fixture',text:'Fixture',audience:[]};
const a=draftWorld(w);a.events.push(event);const b=freezeWorld(finishWorld(a));
requireValue(appendedEventCount(w.events,b.events)===1,'Append proof missing');
const edit=draftWorld(b);edit.events[0].text='Edited';edit.events.push({...event,id:'audit-2'});const c=freezeWorld(finishWorld(edit));
requireValue(appendedEventCount(b.events,c.events)===undefined,'Edited prefix certified as append');
const left=draftWorld(b);left.events.push({...event,id:'left'});const l=freezeWorld(finishWorld(left));
const right=draftWorld(b);right.events.push({...event,id:'right'});const r=freezeWorld(finishWorld(right));
requireValue(appendedEventCount(l.events,r.events)===undefined,'Forked histories shared lineage');
report.push({name:'append-edit-fork-boundaries',passed:true});
let old=structuredClone(w);delete old.perceptionFeatures;const id=old.id;const n=old.nextId;upgradeWorldState(old);D.validateWorldModules(old);
requireValue(old.id===id&&old.nextId===n&&old.perceptionFeatures,'In-place upgrade changed identity');
report.push({name:'in-place-perception-field',passed:true});
const encoded={operations:[{localId:'nav',act:{kind:'invoke',invocation:{family:'follow',x:null,z:null,surfaceId:null,distance:null,targetEntityId:'deer'}},talk:null,think:null,goal:null}]};
const decoded=resolveResponseEntities(encoded,{deer:'deer-1'});
requireValue(decoded.operations[0].act.invocation.targetEntityId==='deer-1','Nested handle not resolved');
report.push({name:'nested-target-reference',passed:true});
const t=D.advanceWorld(w,1);requireValue(t.events.filter(e=>e.type==='encounter').every(e=>e.scope==='private'&&e.audience.length===1),'Acquisition privacy regressed');
requireValue(w.simTime===0&&t.world.simTime===1,'Input mutation');
D.validateWorldModules(t.world);
report.push({name:'native-rebased-transition',events:t.events.length,passed:true});
let mature=structuredClone(w);mature.events=Array.from({length:20000},(_,i)=>({...event,id:'retained-'+i,sequence:i}));mature=freezeWorld(mature);
const times=[];for(let i=0;i<100;i++){const start=performance.now();const d=draftWorld(mature);d.entities[D.PLAYER_ID].actor.energy-=.00001;mature=freezeWorld(finishWorld(d));times.push(performance.now()-start);}
report.push({name:'unchanged-history-native-edits',retainedEvents:20000,edits:100,totalMs:times.reduce((a,b)=>a+b,0),maxMs:Math.max(...times)});
console.log(JSON.stringify(report));
